// Ejected from @docusaurus/theme-classic's DocItem/Paginator. Stock output
// uses `pagination-nav__link--prev` / `pagination-nav__link--next` classes;
// the docs fixture's DOM contract wants plain `.doc-prev` / `.doc-next` <a>
// elements instead, so the whole component is replaced (same rationale as
// DocItem/Content next to it — see that file's comment).
//
// `metadata.previous` / `metadata.next` are computed by
// @docusaurus/plugin-content-docs from the FLATTENED sidebar (a depth-first
// walk of the autogenerated category tree). scripts/gen-docs.mjs lays out
// one category per @otw/docs-data section in SECTIONS order (via each
// section's `_category_.json` `position`) and orders each section's pages
// via `sidebar_position` — the same order @otw/docs-data itself used to
// assign DocPage.order. So the flattened walk reproduces the corpus's
// global reading order exactly, and this component needs no extra logic
// beyond rendering whatever the plugin already computed.
import React from "react";
import Link from "@docusaurus/Link";
import { useDoc } from "@docusaurus/plugin-content-docs/client";

export default function DocItemPaginator() {
  const { metadata } = useDoc();
  const { previous, next } = metadata;
  if (!previous && !next) return null;
  return (
    <nav className="pagination-nav" aria-label="문서 페이지 넘김">
      {previous && (
        <Link className="doc-prev" to={previous.permalink}>
          {previous.title}
        </Link>
      )}
      {next && (
        <Link className="doc-next" to={next.permalink}>
          {next.title}
        </Link>
      )}
    </nav>
  );
}
